package com.haucheng.erp.service;
import com.haucheng.erp.auth.CurrentUserContext; import com.haucheng.erp.dto.DepartmentRequest; import com.haucheng.erp.entity.SysDepartment; import com.haucheng.erp.exception.BusinessException; import com.haucheng.erp.mapper.DepartmentMapper; import com.haucheng.erp.vo.DepartmentView; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class DepartmentService { private final DepartmentMapper mapper; private final OperationLogService operationLog;
 public List<DepartmentView> tree(){List<DepartmentView> source=mapper.selectAll();var current=CurrentUserContext.get();if(current!=null&&!"ALL".equals(current.getDataScope())){Long own=current.getDepartment()==null?null:current.getDepartment().getId();Set<Long> allowed=own==null?Set.of():new HashSet<>(mapper.selectSubtreeIds(own));if("SELF".equals(current.getDataScope()))allowed=own==null?Set.of():Set.of(own);final Set<Long> allowedIds=allowed;source=source.stream().filter(x->allowedIds.contains(x.getId())).toList();}Map<Long,DepartmentView> m=new LinkedHashMap<>();for(DepartmentView v:source)m.put(v.getId(),v);List<DepartmentView> roots=new ArrayList<>();for(DepartmentView v:m.values()){DepartmentView p=v.getParentId()==null?null:m.get(v.getParentId());if(p==null)roots.add(v);else p.getChildren().add(v);}return roots;}
 @Transactional public DepartmentView create(DepartmentRequest r){ensureDepartmentWriteAccess(r.getParentId());String c=r.getDepartmentCode().trim(),n=r.getDepartmentName().trim();unique(c,n,null);validateParent(r.getParentId());validateLeader(r.getLeaderId(),null);SysDepartment d=build(r,c,n);mapper.insert(d);operationLog.record("DEPARTMENT_CREATE",String.valueOf(d.getId()),"创建部门");return find(d.getId());}
 @Transactional public DepartmentView update(Long id,DepartmentRequest r){DepartmentView old=find(id);ensureDepartmentWriteAccess(id);ensureDepartmentWriteAccess(r.getParentId());if(id.equals(r.getParentId()))throw BusinessException.badRequest("上级部门不能是自身");if(isDescendant(id,r.getParentId()))throw BusinessException.badRequest("上级部门不能是下级部门");String c=r.getDepartmentCode().trim(),n=r.getDepartmentName().trim();unique(c,n,id);validateParent(r.getParentId());validateLeader(r.getLeaderId(),id);SysDepartment d=build(r,c,n);d.setId(id);mapper.update(d);operationLog.record("DEPARTMENT_UPDATE",String.valueOf(id),"修改部门");return find(id);}
 @Transactional public void updateStatus(Long id,Boolean s){ensureDepartmentWriteAccess(id);mapper.update(status(id,s));operationLog.record(s?"DEPARTMENT_ENABLE":"DEPARTMENT_DISABLE",String.valueOf(id),s?"启用部门":"停用部门");}
 public DepartmentView find(Long id){DepartmentView view=mapper.selectViewById(id);if(view==null)throw BusinessException.notFound("部门不存在");ensureDepartmentReadAccess(view.getId());return view;}
 private SysDepartment build(DepartmentRequest r,String c,String n){SysDepartment d=new SysDepartment();d.setParentId(r.getParentId());d.setDepartmentCode(c);d.setDepartmentName(n);d.setLeaderId(r.getLeaderId());d.setSortOrder(r.getSortOrder()==null?0:r.getSortOrder());d.setStatus(r.getStatus()==null||r.getStatus());return d;} private SysDepartment status(Long id,Boolean s){SysDepartment d=new SysDepartment();d.setId(id);d.setStatus(s);SysDepartment old=mapper.selectById(id);if(old==null)throw BusinessException.notFound("部门不存在");d.setParentId(old.getParentId());d.setDepartmentCode(old.getDepartmentCode());d.setDepartmentName(old.getDepartmentName());d.setLeaderId(old.getLeaderId());d.setSortOrder(old.getSortOrder());return d;} private void unique(String c,String n,Long id){if(mapper.countByCode(c,id)>0)throw BusinessException.conflict("部门编号已存在");if(mapper.countByName(n,id)>0)throw BusinessException.conflict("部门名称已存在");} private void validateParent(Long id){if(id!=null&&mapper.countActive(id)==0)throw BusinessException.badRequest("上级部门不存在或已停用");} private void validateLeader(Long leaderId,Long departmentId){if(leaderId==null)return;if(departmentId==null?mapper.countLeader(leaderId)==0:mapper.countLeaderInDepartment(leaderId,departmentId)==0)throw BusinessException.badRequest("负责人不存在、已停用或不属于该部门");}
 private void ensureDepartmentReadAccess(Long departmentId){var current=CurrentUserContext.get();if(current==null||"ALL".equals(current.getDataScope()))return;Long own=current.getDepartment()==null?null:current.getDepartment().getId();if(own==null||departmentId==null||("SELF".equals(current.getDataScope())&&!own.equals(departmentId))||("DEPARTMENT".equals(current.getDataScope())&&!mapper.selectSubtreeIds(own).contains(departmentId)))throw BusinessException.forbidden("没有访问该部门数据的权限");}
 private void ensureDepartmentWriteAccess(Long departmentId){var current=CurrentUserContext.get();if(current==null||"ALL".equals(current.getDataScope()))return;if("SELF".equals(current.getDataScope()))throw BusinessException.forbidden("当前数据范围不允许修改部门");Long own=current.getDepartment()==null?null:current.getDepartment().getId();if(own==null||departmentId==null||!mapper.selectSubtreeIds(own).contains(departmentId))throw BusinessException.forbidden("没有访问该部门数据的权限");}
 private boolean isDescendant(Long id,Long candidate){return candidate!=null&&mapper.selectSubtreeIds(id).contains(candidate);}
}
